#!/usr/bin/env python3
"""Run a command with stdout on a pty and stderr on a separate pty, capturing both separately.
Usage: ptysplit.py <outfile_stdout> <outfile_stderr> <cmd> [args...]
"""
import os, sys, select, fcntl, termios, struct

o_out, o_err = sys.argv[1], sys.argv[2]
argv = sys.argv[3:]

rows = int(os.environ.get("PTY_ROWS", "24"))
cols = int(os.environ.get("PTY_COLS", "80"))

m_out, s_out = os.openpty()
m_err, s_err = os.openpty()
for m in (m_out, m_err):
    fcntl.ioctl(m, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

pid = os.fork()
if pid == 0:
    os.setsid()
    fcntl.ioctl(s_out, termios.TIOCSCTTY, 0)
    os.dup2(s_out, 0)
    os.dup2(s_out, 1)
    os.dup2(s_err, 2)
    for f in (m_out, m_err, s_out, s_err):
        try:
            if f > 2:
                os.close(f)
        except OSError:
            pass
    os.execvp(argv[0], argv)
    os._exit(127)

os.close(s_out); os.close(s_err)
bufs = {m_out: [], m_err: []}
open_fds = {m_out, m_err}
while open_fds:
    r, _, _ = select.select(list(open_fds), [], [], 60)
    if not r:
        break
    for fd in r:
        try:
            d = os.read(fd, 65536)
        except OSError:
            d = b""
        if not d:
            open_fds.discard(fd)
        else:
            bufs[fd].append(d)

_, status = os.waitpid(pid, 0)
open(o_out, "wb").write(b"".join(bufs[m_out]))
open(o_err, "wb").write(b"".join(bufs[m_err]))
sys.stderr.write("PTYEXIT=%d\n" % os.waitstatus_to_exitcode(status))

#!/usr/bin/env python3
"""ptymix.py <spec> <outprefix> <cmd...>
spec: 3 chars for fd0,fd1,fd2 -> 't'=pty, 'f'=file, 'n'=/dev/null
Captured pty/file data written to <outprefix>.1 and <outprefix>.2
"""
import os, sys, select, fcntl, termios, struct

spec = sys.argv[1]
pref = sys.argv[2]
argv = sys.argv[3:]

rows = int(os.environ.get("PTY_ROWS", "24"))
cols = int(os.environ.get("PTY_COLS", "80"))

masters = {}
child_fds = {}
files = {}
for i, ch in enumerate(spec):
    if ch == 't':
        m, s = os.openpty()
        fcntl.ioctl(m, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        masters[i] = m
        child_fds[i] = s
    elif ch == 'f':
        p = "%s.%d" % (pref, i)
        fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        child_fds[i] = fd
        files[i] = p
    else:
        child_fds[i] = os.open("/dev/null", os.O_RDWR)

pid = os.fork()
if pid == 0:
    for i in (0, 1, 2):
        os.dup2(child_fds[i], i)
    for f in set(list(masters.values()) + list(child_fds.values())):
        if f > 2:
            try: os.close(f)
            except OSError: pass
    os.execvp(argv[0], argv)
    os._exit(127)

for f in child_fds.values():
    if f > 2:
        try: os.close(f)
        except OSError: pass

bufs = {m: [] for m in masters.values()}
open_fds = set(masters.values())
while open_fds:
    r, _, _ = select.select(list(open_fds), [], [], 60)
    if not r: break
    for fd in r:
        try: d = os.read(fd, 65536)
        except OSError: d = b""
        if not d: open_fds.discard(fd)
        else: bufs[fd].append(d)

_, status = os.waitpid(pid, 0)
for i, m in masters.items():
    open("%s.%d" % (pref, i), "wb").write(b"".join(bufs[m]))
sys.stderr.write("PTYEXIT=%d\n" % os.waitstatus_to_exitcode(status))
